Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='remembercard', at=datetime(2026, 10, 3, 0, 0, 0), actor='assistant', title='A remember card names its words and never holds them', body="A REMEMBER CARD NAMES ITS WORDS, NEVER HOLDS THEM (2026-10-03): its `Asked` carries the memory's salted `TextName`, the words live in the memory's text store, and the one sweep (`secretary::texts::dead`, over every history's naming, under the memory's hold) deletes them once nothing live names them, so dismissing the card, or forgetting the fact it became, erases them while the history stays.", rationale='Decided 2026-10-03.', supersedes=()))